apply_name(0x102A5D20, 'sqimTM2Composite', 'Validates matching dimensions between two images, then performs a per-pixel masked overlay: copies source pixels into the destination only where the destination pixel is currently 0 (transparent/empty). The compositing half of the TM2 name-matched texture pool system.', True)
apply_name(0x102A64D0, 'sqimTM2LoadFile', "Real, complete TM2 file loader. Parses the TM2 header, reads CLUT/palette data for indexed formats (matches the confirmed 'CLUT data' string found elsewhere), allocates and reads pixel data. Checks sqimTM2FindExisting for a matching texture (by dimensions); if found, calls sqimTM2Composite to layer the new data onto it rather than replacing it; otherwise creates fresh. Very plausibly the real mechanism behind character-customization texture layering (dye colors/tattoos onto a base skin texture), though not confirmed to that specific use case by any direct string.", True)
apply_name(0x102A6820, 'sqimTM2FindExisting', "Name-based texture cache/pool lookup: walks a linked list of 'buckets' (dword_109A2864), strips file extensions, and checks for a matching base filename with a literal 'RT' prefix (checked as ASCII bytes, not a guess) -- very likely 'ReTexture,' a customization/dye naming convention.", True)
apply_name(0x102A96C0, 'sqVtxPrint', "Real, confirmed name (own debug string: 'sqVtx <%x> (%d vertices)'). A vertex format is fully sparse -- any subset of the 12 sqVtx_GetFieldTypeName fields can be present depending on what a shape actually needs.", True)
apply_name(0x102A9850, 'sqVtx_GetFieldTypeName', "CAPSTONE FINDING: the complete, real vertex-attribute taxonomy for sqVtx (sqBase module), the generic vertex-format base shared across all sqShape geometry types. 12 real, confirmed field slots: 0=Points, 1=Normals, 2=UVs, 3=Colors, 4=UTangents, 5=VTangents (full tangent-space data, matches sqShader Generic's bumptexture parameter), 6=Parents (bone/hierarchy parent index), 7=DeformationWeights, 8/9=DeformationMatrix (two slots), 10=User0, 11=User1. DeformationWeights/DeformationMatrix ARE the real, named vertex-attribute fields holding the bone-weight data SkinVertices was reverse-engineered to consume -- confirmed from the data-format side, closing the loop with sqinCluster and sqinSkinBuildBinary: four independent confirmations of the same skinning structure from four different angles.", True)
apply_name(0x102AC540, 'sqshTriStripZSort', "REAL PERFORMANCE-RELEVANT FINDING: a genuine per-triangle transparency depth-sort, confirmed via its own error string. Computes a view-space depth key per triangle (painter's-algorithm centroid-dot-view-direction), then dispatches to a recursive range-based sort. Confirmed real: shadow volumes only work with sqshTriStrip shapes specifically. No dirty-flag/'view changed' gating visible -- if run every frame for every transparent triangle-strip shape, this is real, non-trivial CPU cost distinct from CXiActorDraw's object-level depth sort. A real candidate for profiling, not confirmed as a problem.", True)
apply_name(0x102ACC30, 'sqshPointsPrint', 'Confirmed real, built on the shared sqVtx base. Plausibly used for particle/billboard VFX geometry.', True)
apply_name(0x102AD090, 'sqshCurvesPrint', 'Real, confirmed fields: curve count, precision, and per-curve control-point counts, built on sqVtx. A classic technique for spline-based trail effects.', True)
apply_name(0x102AEB40, 'sqinShape_Blend4Bone', 'A genuine 4-bone weighted blend: gathers one component at a time from 4 separate source streams (via PackVec4) into 4-vectors, then transforms each through a shared matrix via Mat4x4_TransformVec4. The classic shape of hardware-style 4-bone-per-vertex skinning, implemented via matrix math -- a second, different implementation of the same underlying idea as the weight-table lookup already confirmed in SkinVertices; keep the two distinct, not conflated.', True)
apply_name(0x102AEC80, 'sqinShape_Clear', "Frees two buffers (likely vertex and normal data) gated behind a 'built' flag bit, matching the lifecycle pattern confirmed elsewhere in this middleware. sqinShape's own constructor was also located (allocates 16 bytes, tagged to sqinShape.c line 33) but sits in a gap IDA's auto-analysis didn't mark as a function boundary -- not force-renamed.", True)
apply_name(0x102AF540, 'sqinCluster_Create', "Allocates 160 bytes (sqinCluster's confirmed object size), calls sqinCluster_Init.", True)
apply_name(0x102AF570, 'sqinCluster_Init', "Sets up sqinCluster's manual C-style function-pointer table (not real C++ vtable dispatch -- portable-middleware style), including sqinCluster_Dump.", True)
apply_name(0x102AF630, 'sqinCluster_Dump', "Debug dump function revealing sqinCluster's real field layout via its own print labels: 'shape' (+0x1C, a 0x3C/60-byte sub-object -- matches the confirmed 60-byte vertex-record stride in SkinVertices exactly), 'trsMat' (+0x58), 'nTrsMat' (+0x5C), 'jointNode' (+0x9C, the bone this cluster is weighted to). Direct confirmation that sqinCluster IS the real 'bone weight group' object inferred by hand in SkinVertices.", True)
apply_name(0x102AFBA0, 'sqScript_ReadToken', 'Real, reusable text-script tokenizer. Very likely shared infrastructure with sqmdScript.c/sqParser.c -- one script-parsing system used across multiple asset types, not shader-specific.', True)
apply_name(0x102B2DE0, 'sqshDraw_Submit', "The real per-frame draw-submission function. Confirmed via its own error string ('empty or missing vertex, can't draw'). Sets up device state, then dispatches by primitive-topology mode into sqgxContext_BatchIndices.", True)
apply_name(0x102B4070, 'sqshUtil_WeldVertices', 'Real vertex-welding function, but notably does NOT use the spatial grid confirmed in sqshIndex_BuildSpatialGrid -- a separate, naive O(n^2) all-pairs distance comparison instead. Not confirmed whether this is only used for small vertex counts or a real missed-optimization opportunity.', True)
apply_name(0x102B44E0, 'sqshStrip_GenerateFromTriangles', "REAL, CONFIRMED PERFORMANCE OPTIMIZATION: a genuine, sophisticated triangle-strip generation algorithm, confirmed via its own debug output ('total nb triangles', 'nb meshes', 'averaged strip length', 'nb independent triangles'). Builds a triangle-adjacency graph, then greedily grows strips using a priority-bucket structure -- a classic technique from real period strip-generation algorithms. Legitimate, well-implemented geometry optimization.", True)
apply_name(0x102B5DA0, 'sqshQuadMeshPrint', 'Real, confirmed fields: type, a quads count, a mesh array (element count + length), and a conditional facet-normals count.', True)
apply_name(0x102BA500, 'sqshIndex_BuildSpatialGrid', 'Real, confirmed spatial hash grid builder: allocates a uniform 15x15x15 grid (3375 cells) sized from an input bounding box. Almost certainly used for vertex welding -- merging duplicate/nearby vertices efficiently when building an index buffer from raw geometry, avoiding an O(n^2) all-pairs check.', True)
apply_name(0x10311BBB, 'Allocator_Generic', 'The allocator CMoDistRingElem_AllocRingGeometry calls with its computed buffer size. Not otherwise characterized -- likely a generic heap-allocation wrapper used well beyond this one call site.', True)

