apply_name(0x1000CFB0, 'CAcc_Constructor', 'Sets the CAcc vtable (0x10329A3C) and zeroes the three COM pointers at +4/+8/+0xC. Constructed by CDx_Constructor (x4), CMoOcclusionMng (sub_1006C140), sub_10044270 and sub_100755A0. CAcc has no methods beyond the shared base slots and a destructor, so the pointers are filled by owner code (not yet identified).', True)
apply_name(0x100394D0, 'ThreadPool_StartThread', "Thread-pool start wrapper (capacity 9: 'Thread Num Over!!' / 'Thread Create Error!!'). Exactly one caller: LobbyThread_Start.", True)
apply_name(0x100AC2F0, 'CXiDollActor_thunk_C4_0', "imm32 this-adjusting thunk: sub ecx, 0C4h ; jmp 0x100ABCA0. One of exactly four such thunks in the binary, all for CXiDollActor's secondary base at +0xC4 (see CXiDollActor_vtbl_secondary_C4).", True)
apply_name(0x100AC300, 'CXiDollActor_thunk_C4_1', 'imm32 this-adjusting thunk: sub ecx, 0C4h ; jmp 0x100ABE80.', True)
apply_name(0x100AC310, 'CXiDollActor_thunk_C4_2', 'imm32 this-adjusting thunk: sub ecx, 0C4h ; jmp 0x100AC070.', True)
apply_name(0x100AC320, 'CXiDollActor_thunk_C4_3', 'imm32 this-adjusting thunk: sub ecx, 0C4h ; jmp 0x100AC0B0.', True)
apply_name(0x100C5C00, 'CXiSkeletonActor_DestructorBody', "Releases resources and destroys the owned async skeleton-load task at +0xA08 (calls its vtable slot 6, scalar-deleting destructor, then clears the field) -- the actor owns the task. Decrements the actor's two update-bucket counters.", True)
apply_name(0x100C5D60, 'CXiSkeletonActor_Init', "Init/reset. Sets opacity (+0x59C, likely XiControlActor::alpha_base) to 0 so actors fade in; color +0x660 = 0x80808080 and mtex_alpha/shadow_alpha (+0x668/+0x66C) = 128 (PS2 '0x80 = 1.0' convention); animation-name table 'idl?wlk?run?btl?' at +0x7C8; +0xA08 = 0; assigns the actor to the least-loaded of four buckets in g_actorUpdateBucketCountA/B (indices at +0x9F0/+0x9FC; used by sub_100CBDE0 to run work every fourth frame).", True)
apply_name(0x100D2F40, 'CXiSkeletonActor_OnSkeletonLoaded', 'Completion callback passed to CXiSkeletonActorRes_Constructor by CXiSkeletonActor_LoadSkeletonResource (stored at task+0x38). Name from role; body not analyzed.', True)
apply_name(0x100D2F60, 'CXiSkeletonActor_LoadSkeletonSync', 'Synchronous skeleton-load path taken by CXiSkeletonActor_LoadSkeletonResource for special-case actors (vtable slot 193 true, or +0x70 sub-object flag 0x80/0x100), and as the fallback if task allocation fails.', True)
apply_name(0x100D7050, 'CXiSkeletonActorRes_Destructor', "Restores the vtable, clears g_pActiveSkeletonActorRes if it points at this task, clears the linked actor's +0xA08 back-reference, then runs the CMoTask base destructor (sub_100747C0).", True)
apply_name(0x100D70A0, 'CXiSkeletonActorRes_ProcessLoadState', 'State machine for the async skeleton load: reads the load state at +0x3C, uses CXiSkeletonActorRes_GetLinkedActor, and gates assignment of g_pActiveSkeletonActorRes.', True)
apply_name(0x10245600, 'LobbyThread_Start', "Creates the thread pool (g_pLobbyThreadPool) and starts the game's only pooled worker, LobbyThread_Main.", True)
apply_name(0x1026DF00, 'sqxfXformTD_Init', 'Writes the sqObject header / manual vtable: type 0xC0003 (SQXF_XFORMTD_TYPE), +0x08 Validate, +0x0C Destroy, +0x10 Print, +0x14 active=0xFF, +0x18 Update. Zeroes position +0x5C, identity quaternion +0x68, scalar +0x78 = 1.0. Layout matches the PS2 sqObject/sqUpdater debug types exactly.', True)
apply_name(0x1026DF80, 'sqxfXformTD_Validate', "Stub: prints 'WARNING: sqxfXformTDValidate not implemented.' and returns true.", True)
apply_name(0x1026DF90, 'sqxfXformTD_Destroy', 'Frees the object (sqxfXformTD.c line 99).', True)
apply_name(0x1026DFD0, 'sqxfXformTD_Copy', 'Second constructor: allocates another 0x7C-byte sqxfXformTD (sqxfXformTD.c line 126) and copies position/quaternion/scalar from the source -- a copy/clone.', True)
apply_name(0x1026E040, 'sqxfXformTD_Print', "Debug dump ('sqxfXformTD <%x>').", True)
apply_name(0x1029B250, 'sqshTriStrip_ThrottledZSortUpdate', 'Only caller of sqshTriStripZSort. Increments a counter at +32 each call and sorts only when it reaches the per-shape period at +28, then resets -- the Z-sort is throttled, not per-frame. Eye position and view direction come from the combined matrix.', True)
apply_name(0x102A0350, 'sqmdScriptCmd_skeleton_shape', "Handler for the model-assembly script command 'skeleton_shape' (registered in g_modelScriptCommandTable). One of the construction-time routes into sqsdSampling_BakeOntoShape.", True)

