apply_name(0x10039E50, 'TexObj_Upload', 'CPU-converts a texture object into a staging D3DXCreateTexture surface (LockRect/UnlockRect; rows flipped, CLUT expanded for 4/8-bit, PS2 alpha range kept), then D3DXLoadSurfaceFromSurface into level 0 (FILTER_NONE; this is where DXT encoding happens) and builds mips level-by-level (FILTER_BOX). Precompressed DXT data goes straight in via D3DXLoadSurfaceFromMemory (FOURCC table 0x10351C94). Cube faces per face.', True)
apply_name(0x10039A80, 'TexObj_Create', "Chooses the final format and creates the D3D texture: A1R5G5B5 / A8R8G8B8, or DXT1 (16-bit sources) / DXT3 (32-bit sources) when the object's compression class (flags>>4&0xF) is allowed by g_cfgTextureCompression (registry 0018) or, for class 10, g_cfgMapCompression (registry 0019). Mip count forced to 1 below 32 px. Non-power-of-two sizes are read back after upload. Then calls TexObj_Upload.", True)
apply_name(0x10039A30, 'TexObj_CreateAndUpload', 'TexObj_Create, then state (+0x3C) = 3 (ready) and drops the source-resource reference at +8.', True)
apply_name(0x10039A60, 'TexObj_Reupload', 'Re-uploads into existing D3D objects (after device loss), state = 3.', True)
apply_name(0x10039920, 'TexObj_Constructor', '72-byte texture object: +0x1C CLUT, +0x20 pixels, +0x24/+0x26 w/h, +0x28 src bpp, +0x29 dst format (bit7 = precompressed), +0x2A mips, +0x2C flags, +0x38 next, +0x3C state, +0x40 IDirect3DTexture8*, +0x44 IDirect3DCubeTexture8*.', True)
apply_name(0x1003ABB0, 'TexMgr_UploadPump', 'Per-frame upload pump over the texture list: state 1 -> create+upload, state 2 -> release+reupload. In-game (scene state 0x60) and not in immediate mode (mgr+0x10 == 0) it stops after 20 uploads per frame.', True)
apply_name(0x1003AB70, 'TexMgr_UploadPumpEntry', 'Called from Frame_Render right after BeginScene; forwards to TexMgr_UploadPump.', True)
