apply_name(0x1001D800, 'TexRes_LoadBm2', 'Texture resource loader slot (CMoResource-derived vtable near 0x1032C8CC). Checks the "Bm2" version nibble, dedupes by name, builds a TexObj and enqueues it (or uploads synchronously in immediate mode).', True)
